public class ExceptionOrder {
    public static void main(String[] args) {
        String[] inputs = {"4", "x", "0"};
        for (String s : inputs) {
            try {
                int n = Integer.parseInt(s);
                System.out.println(100 / n);
            } catch (NumberFormatException | ArithmeticException e) {
                System.out.println("Bad input: " + s);
            }
        }
    }
}
